const raw = $input.first().json;
const body = raw.body || raw;

const evento = (body?.event || '').toLowerCase();
const fromMe = body?.data?.key?.fromMe ?? false;
const remoteJid = body?.data?.key?.remoteJid || '';
const messageId = body?.data?.key?.id || '';
const instance = body?.instance || body?.instanceName || '';

const msg = body?.data?.message || {};
const text = msg.conversation || msg.extendedTextMessage?.text || '';
const hasContent = !!(text || msg.audioMessage || msg.imageMessage || msg.locationMessage);
const pushName = body?.data?.pushName || '';

const isMessage = evento.includes('messages');
const isGroup = remoteJid.endsWith('@g.us');

if (!isMessage || isGroup || !hasContent || (fromMe && !text.trim().startsWith('#'))) {
  return [];
}

// Detectar localização enviada (para entrega)
const location = msg.locationMessage ? {
  lat: msg.locationMessage.degreesLatitude,
  lng: msg.locationMessage.degreesLongitude
} : null;

return [{
  json: {
    instance: String(instance),
    remoteJid,
    telefone: remoteJid.replace(/@s\.whatsapp\.net$/, ''),
    text: text || (location ? 'Localização enviada' : ''),
    pushName,
    fromMe,
    evento,
    messageId,
    location,
    body
  }
}];

const txt = v => (v == null || v === '') ? '' : String(v).trim();

let f = {};
try { f = $('Filtro + Extrair').first().json; } catch { f = {}; }

const telefone = txt(f.telefone);
const pushName = txt(f.pushName);
const fromMe = f.fromMe ?? false;
const inst = txt(f.instance);
const text = txt(f.text);
const messageId = txt(f.messageId);
const location = f.location || null;

let raw = [];
try { raw = $('Carregar Dados Negócio').all().map(i => i.json); } catch { raw = []; }

if (raw.length === 0) {
  return [{ json: { erro: 'Restaurante não encontrado.', instancia_recebida: inst } }];
}

const n = raw[0];
const instFinal = inst || txt(n.instancia_whatsapp);

let infoPag = '';
if (txt(n.chave_pix)) {
  infoPag += 'PIX ' + txt(n.tipo_chave_pix).toUpperCase() + ': ' + txt(n.chave_pix);
  if (txt(n.nome_titular_pix)) infoPag += ' | Titular: ' + txt(n.nome_titular_pix);
  if (txt(n.banco_pix)) infoPag += ' | ' + txt(n.banco_pix);
}
if (n.aceita_cartao) infoPag += (infoPag ? ' | ' : '') + 'Cartão na entrega/maquininha';
infoPag += (infoPag ? ' | ' : '') + 'Dinheiro (troco disponível)';

// Determinar período do dia para sugestões contextuais
const hora = new Date().getHours() - 3; // Ajuste fuso BRT
let periodo = 'dia';
if (hora >= 6 && hora < 11) periodo = 'manha';
else if (hora >= 11 && hora < 15) periodo = 'almoco';
else if (hora >= 15 && hora < 18) periodo = 'tarde';
else if (hora >= 18 && hora < 23) periodo = 'noite';
else periodo = 'madrugada';

return [{ json: {
  instancia: instFinal,
  cliente_id: n.cliente_id ?? n.id ?? null,
  session_id: instFinal + '_' + telefone,
  nome_empresa: txt(n.nome_empresa) || 'Restaurante',
  nome_proprietario: txt(n.nome_proprietario),
  telefone_empresa: txt(n.telefone),
  endereco: txt(n.endereco),
  horario_funcionamento: txt(n.horario_funcionamento) || 'Horário comercial',
  formas_pagamento: txt(n.formas_pagamento) || 'Pix, Cartão, Dinheiro',
  informacoes_extras: txt(n.informacoes_extras),
  nome_atendente_ia: txt(n.nome_atendente_ia) || 'Atendente Virtual',
  tom_voz: txt(n.tom_voz) || 'Simpática, ágil e prestativa',
  telefone, pushName, fromMe, text, messageId, location,
  telefone_proprietario: txt(n.telefone),
  remoteJid: telefone + '@s.whatsapp.net',
  evo_api_url: txt(n.evo_api_url) || 'https://evo.upviaagentes.com',
  evo_api_key: txt(n.evo_api_key) || '3gl0eq56t0ahsh3m5lx7ruv8i764qcvd',
  catalogo_sheets_id: txt(n.catalogo_sheets_id),
  chave_pix: txt(n.chave_pix),
  tipo_chave_pix: txt(n.tipo_chave_pix),
  nome_titular_pix: txt(n.nome_titular_pix),
  banco_pix: txt(n.banco_pix),
  info_pagamento: infoPag,
  aceita_cartao: n.aceita_cartao || false,
  link_checkout: txt(n.link_checkout),
  tempo_preparo_medio: n.tempo_preparo_medio || 40,
  taxa_entrega_padrao: n.taxa_entrega_padrao || 5,
  raio_entrega_km: n.raio_entrega_km || 10,
  pedido_minimo: n.pedido_minimo || 0,
  aceita_retirada: n.aceita_retirada ?? true,
  msg_pos_pedido: txt(n.msg_pos_pedido),
  periodo
} }];

// Cardápio
let cardapioItems = [];
try { cardapioItems = $('Carregar Cardápio').all().map(i => i.json); } catch {}

let cardapio = '';
if (cardapioItems.length > 0) {
  // Agrupar por categoria
  const categorias = {};
  for (const item of cardapioItems) {
    if (item.disponivel === 'não' || item.disponivel === 'nao' || item.disponivel === false) continue;
    const cat = item.categoria || item.Categoria || 'Outros';
    if (!categorias[cat]) categorias[cat] = [];
    const nome = item.nome || item.Produto || item.Nome || 'Item';
    const preco = item.preco || item.Preço || item.valor || '?';
    const desc = item.descricao || item.Descrição || '';
    const adicionais = item.adicionais || item.Adicionais || '';
    const tamanhos = item.tamanhos || item.Tamanhos || '';
    categorias[cat].push(`${nome} — R$ ${preco}${desc ? ' (' + desc + ')' : ''}${adicionais ? ' | Adicionais: ' + adicionais : ''}${tamanhos ? ' | Tamanhos: ' + tamanhos : ''}`);
  }
  for (const [cat, items] of Object.entries(categorias)) {
    cardapio += `\n[${cat.toUpperCase()}]\n`;
    items.forEach((item, i) => { cardapio += `  ${i+1}. ${item}\n`; });
  }
} else {
  cardapio = 'Cardápio indisponível no momento. Pergunte ao atendente.';
}

// Taxas de entrega
let taxas = '';
try {
  const taxaItems = $('Carregar Taxas').all().map(i => i.json);
  if (taxaItems.length > 0) {
    taxas = taxaItems.map(t => {
      const bairro = t.bairro || t.Bairro || t.regiao || 'Região';
      const taxa = t.taxa || t.Taxa || t.valor || '0';
      const tempo = t.tempo_estimado || t.Tempo || '';
      return `${bairro}: R$ ${taxa}${tempo ? ' (~' + tempo + ' min)' : ''}`;
    }).join(' | ');
  }
} catch {}

// Promoções ativas
let promos = '';
try {
  const promoItems = $('Carregar Promos').all().map(i => i.json);
  const ativas = promoItems.filter(p => p.ativa === 'sim' || p.ativa === true || p.Ativa === 'sim');
  if (ativas.length > 0) {
    promos = ativas.map(p => {
      const nome = p.nome || p.Nome || 'Promoção';
      const desc = p.descricao || p.Descrição || '';
      const preco = p.preco_promo || p.Preço || '';
      const validade = p.validade || p.Validade || '';
      return `${nome}${desc ? ': ' + desc : ''}${preco ? ' — R$ ' + preco : ''}${validade ? ' (até ' + validade + ')' : ''}`;
    }).join(' | ');
  }
} catch {}

const ctx = $('Montar Contexto Dinâmico').first().json;

return [{ json: { ...ctx, cardapio, taxas_entrega: taxas || 'Taxa padrão: R$ ' + (ctx.taxa_entrega_padrao || 5), promos_ativas: promos || 'Nenhuma promoção ativa no momento' } }];

